<script setup lang="ts">
import {ref,reactive,computed,watch} from 'vue'
import {ElMessageBox} from 'element-plus'
import {queuePrice} from './priceJobs'
import type {Listing,Pricing,SubmitPreview,Submission} from './listingTypes'
const props=defineProps<{row:Listing|null}>(),emit=defineEmits<{close:[],saved:[],editing:[value:boolean],busy:[value:boolean]}>()
const loading=ref(false),saving=ref(false),error=ref(''),data=ref<Pricing|null>(null),baseline=ref(''),preview=ref<SubmitPreview|null>(null)
const form=reactive({price:'',sale_price:'',dates:[] as Date[]|null})
const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone
const dirty=computed(()=>JSON.stringify(form)!==baseline.value)
watch(dirty,v=>emit('editing',v))
async function request(suffix:string,body?:unknown){const r=await fetch(`/api/listings/${props.row!.id}/${suffix}`,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-ERP-Client':'web'},body:body===undefined?undefined:JSON.stringify(body)});const d=await r.json();if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'价格或日期格式不正确');return d}
function hydrate(p:Pricing){data.value=p;form.price=p.price||'';form.sale_price=['active','scheduled'].includes(p.sale_status)?p.sale_price||'':'';form.dates=form.sale_price&&p.sale_start&&p.sale_end?[new Date(p.sale_start),new Date(p.sale_end)]:[];baseline.value=JSON.stringify(form)}
watch(()=>props.row,row=>{preview.value=null;error.value='';if(!row){emit('editing',false);return}hydrate(row.pricing)})
function legacy(){const d=data.value?.draft?.changes;if(!d)return;form.price=d.price||form.price;form.sale_price=d.sale_price||'';form.dates=d.sale_price&&d.sale_start&&d.sale_end?[new Date(d.sale_start),new Date(d.sale_end)]:[]}
function validation(){if(!/^\d+(\.\d{1,2})?$/.test(form.price)||Number(form.price)<=0)return '请填写有效售价，最多两位小数';if(form.sale_price){if(!/^\d+(\.\d{1,2})?$/.test(form.sale_price)||Number(form.sale_price)<=0)return '请填写有效促销价，最多两位小数';if(form.dates?.length!==2)return '填写促销价时必须填写开始和结束时间';if(form.dates![1]<=form.dates![0])return '促销结束时间必须晚于开始时间';if(form.dates![1].getTime()<=Date.now())return '促销结束时间必须晚于当前时间';if(Number(form.sale_price)>=Number(form.price))return '促销价必须低于售价'}else if(form.dates?.length)return '未填写促销价，请清空促销时间';return ''}
async function submitPreview(){error.value=validation();if(error.value||!data.value||!props.row)return;const row=props.row;const body={price:form.price,sale_price:form.sale_price||null,sale_start:form.sale_price?form.dates![0].toISOString():null,sale_end:form.sale_price?form.dates![1].toISOString():null};baseline.value=JSON.stringify(form);emit('editing',false);emit('close');queuePrice(row,body)}
async function submitted(s:Submission){if(['accepted','verified'].includes(s.status))baseline.value=JSON.stringify(form);emit('saved')}
async function close(){if(saving.value)return;if(dirty.value&&!loading.value){try{await ElMessageBox.confirm('尚有未提交的调价内容，确定关闭？','关闭调价',{confirmButtonText:'放弃编辑并关闭',cancelButtonText:'继续编辑'})}catch{return}}emit('close')}
</script>
<template><el-dialog :model-value="!!row" title="调价" width="520px" :before-close="close" :close-on-click-modal="false" destroy-on-close class="listing-price-dialog"><div><p class="price-sku">{{row?.sku}}</p><p class="muted">{{row?.store}} · {{row?.marketplace}} · {{data?.currency||'—'}} · 提交后后台处理</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button v-if="data?.draft&&Object.keys(data.draft.changes).length" link @click="legacy">载入旧版未提交的调价内容</el-button><div v-if="data" class="current-price">{{data.price_source==='current_offer'?'当前普通买家报价':'本地售价'}}：{{data.price||'—'}} {{data.currency}}<br>促销价：{{data.sale_price||'—'}}</div><p v-if="data?.price_source==='current_offer'" class="muted">亚马逊未返回常规售价，此处使用当前普通买家报价。促销信息以已返回的价格计划为准；提交将调整普通售价，企业价和阶梯折扣保持不变。</p><el-form label-position="top" :disabled="saving||!data"><el-form-item label="售价" required><el-input v-model="form.price" inputmode="decimal" aria-label="售价"><template #append>{{data?.currency}}</template></el-input></el-form-item><el-form-item label="促销价"><el-input v-model="form.sale_price" inputmode="decimal" clearable aria-label="促销价"><template #append>{{data?.currency}}</template></el-input></el-form-item><el-form-item label="促销时间范围" :required="!!form.sale_price"><el-date-picker v-model="form.dates" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间" format="YYYY-MM-DD HH:mm" :clearable="true" style="width:100%"/></el-form-item><p class="muted">时间按 {{timezone}} 填写。促销价必须提供完整时间范围；清空促销价及时间表示取消促销。</p></el-form></div><template #footer><el-button @click="close">关闭</el-button><el-button type="primary" :loading="saving" :disabled="!data||!dirty" @click="submitPreview">提交调价</el-button></template></el-dialog></template>
<style scoped>.price-sku{font-weight:600;overflow-wrap:anywhere}.current-price{margin:16px 0;padding:12px;background:#f5f8f6;border-radius:7px;line-height:1.9;font-size:12px}.muted{font-size:11px;line-height:1.8}</style>
